void _pruneExpiredOfficialAlerts() {
  final previous = _officialAlertReport;
  if (previous == null) return;
  final report = previous.validCachedAlertsAt(DateTime.now(), fallbackCheckedAt: _alertsChecked);
  if (report.alerts.length == previous.alerts.length) return;
  setState(() {
    _officialAlertReport = report;
    activeOfficialAlerts = report.alerts;
    officialAlertStatus = report.statusText(cached: _officialAlertsAreCached);
    _alertsChecked = null;
    _lastAlertsAttempt = null;
  });
}

if (!mounted) return;
// The existing minute tick/resume path also removes expired alert names
// while a longer network refresh is still in progress.
_pruneExpiredOfficialAlerts();
if (_refreshing) return;

final received = _dateFromMillis(
  prefs.getInt('seapoint_official_alert_report_received_v2'),
) ?? saved;
OfficialAlertFeed? report;
final rawReport = prefs.getString('seapoint_official_alert_report_v2');
if (rawReport != null) {
  try {
    final decoded = jsonDecode(rawReport);
    if (decoded is Map<String, dynamic>) {
      report = OfficialAlertFeed.fromJson(decoded);
    }
  } catch (e) {
    debugPrint('Alert report cache: $e (trying legacy names)');
  }
}
if (report == null) {
  final raw = prefs.getString('seapoint_official_alerts_v1');
  if (raw == null) return;
  final decoded = jsonDecode(raw);
  if (decoded is! List) return;
  report = OfficialAlertFeed.fromLegacyCache(decoded, checkedAt: saved);
}
if (!mounted) return;
final restored = report.validCachedAlertsAt(DateTime.now(), fallbackCheckedAt: saved);

_officialAlertReport = restored;
_officialAlertsAreCached = true;
activeOfficialAlerts = restored.alerts;
_alertsChecked = received;
officialAlertStatus = restored.statusText(cached: true);

await prefs.setString('seapoint_official_alert_report_v2', jsonEncode(report.toJson()));
// Keep the previous names-only cache usable if the client is rolled back.
await prefs.setString('seapoint_official_alerts_v1', jsonEncode(report.alerts));
await prefs.setInt('seapoint_official_alert_report_received_v2', DateTime.now().millisecondsSinceEpoch);
final originalObservation = report.oldestAlertObservation;
if (originalObservation != null) {
  await prefs.setInt('seapoint_official_alerts_checked', originalObservation.millisecondsSinceEpoch);
} else if (report.alerts.isEmpty) {
  await prefs.setInt('seapoint_official_alerts_checked', DateTime.now().millisecondsSinceEpoch);
} else {
  await prefs.remove('seapoint_official_alerts_checked');
}

void _officialAlertRefreshUnavailable() {
  if (!mounted) return;
  final previous = _officialAlertReport?.validCachedAlertsAt(
    DateTime.now(), fallbackCheckedAt: _alertsChecked,
  );
  final report = OfficialAlertFeed.fromJson({
    ...?previous?.toJson(),
    'alerts': previous?.alerts ?? <String>[],
    'links': previous?.links ?? <String, String>{},
    'status': 'unavailable',
    'client_error': 'Latest alert refresh unavailable',
  });
  setState(() {
    _officialAlertReport = report;
    _officialAlertsAreCached = previous != null;
    activeOfficialAlerts = report.alerts;
    officialAlertStatus = report.alerts.isNotEmpty
        ? report.statusText(cached: true)
        : report.statusText(unavailable: true);
  });
}

// Partial/unknown empty reports deliberately use 503 so older clients do
// not mistake them for verified absence. The new client reads their
// structured status and per-source coverage on both supported statuses.
final receivedAt = DateTime.now();
final report = parseOfficialAlertResponse(response.statusCode, response.body)
    .recordingObservation(receivedAt, previous: _officialAlertReport)
    .validCachedAlertsAt(receivedAt)
    .retainingUnverifiedAlerts(
      _officialAlertReport, now: receivedAt, fallbackLinks: _bulletinUrls,
    );

_alertsChecked = receivedAt;
_officialAlertReport = report;
_officialAlertsAreCached = false;
activeOfficialAlerts = report.alerts;
officialAlertStatus = report.statusText();
